import static org.mockito.Mockito.*;

public class BeanDeserializerBase_deserializeFromBoolean_TriageGen1Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private ValueInstantiator instantiator;
    private JsonDeserializer<Object> delegateDeserializer;
    private BeanDeserializerBase beanDeserializerBase;

    @Before
    public void setUp() throws Exception {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        instantiator = mock(ValueInstantiator.class);
        delegateDeserializer = mock(JsonDeserializer.class);

        // Since BeanDeserializerBase is abstract, we use a subclass or a mock
        // However, to test the logic inside the method, we use a spy on a real implementation or a mock that allows field injection
        beanDeserializerBase = mock(BeanDeserializerBase.class, withSettings().useConstructor(
                mock(BeanDeserializerBuilder.class), 
                mock(BeanDescription.class), 
                mock(BeanPropertyMap.class), 
                mock(java.util.Map.class), 
                mock(java.util.Set.class), 
                true, 
                false
        ).defaultAnswer(CALLS_REAL_METHODS));

        // Inject protected fields via reflection because they are private/protected in the base class
        setField(beanDeserializerBase, "_valueInstantiator", instantiator);
        setField(beanDeserializerBase, "_delegateDeserializer", delegateDeserializer);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getSuperclass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    /**
     * Test Path 1: _delegateDeserializer is NOT null AND _valueInstantiator.canCreateFromBoolean() is FALSE
     * This tests the delegation logic and injectValues.
     */
    @Test
    public void testDeserializeWithDelegateAndCannotCreateFromBoolean() throws IOException {
        Object delegateResult = new Object();
        Object finalBean = new Object();

        when(instantiator.canCreateFromBoolean()).thenReturn(false);
        when(delegateDeserializer.deserialize(p, ctxt)).thenReturn(delegateResult);
        when(instantiator.createUsingDelegate(ctxt, delegateResult)).thenReturn(finalBean);

        // To test injectValues, we need to ensure _injectables is not null
        // We use a spy to verify the call to the protected method if possible, 
        // but since we can't easily mock the protected call on the same object without a real subclass,
        // we rely on the fact that the code calls injectValues(ctxt, bean).

        // We'll create a real subclass to test the injection branch properly
        BeanDeserializerBase realBean = new BeanDeserializerBase(
                mock(BeanDeserializerBuilder.class), mock(BeanDescription.class), 
                mock(BeanPropertyMap.class), mock(java.util.Map.class), 
                mock(java.util.Set.class), true, false) {
            @Override public JsonDeserializer<Object> unwrappingDeserializer(com.fasterxml.jackson.databind.NameTransformer unwrapper) { return null; }
            @Override protected BeanDeserializerBase asArrayDeserializer() { return null; }
            @Override public void resolve(DeserializationContext ctxt) throws com.fasterxml.jackson.databind.JsonMappingException {}
            @Override public Object deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
            @Override public Object deserializeWithType(JsonParser p, DeserializationContext ctxt, com.fasterxml.jackson.databind.deser.std.TypeDeserializer typeDeserializer) throws IOException { return null; }
            @Override public Object deserializeFromObjectUsingNonDefault(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
            @Override protected Object _deserializeUsingPropertyBased(JsonParser p, DeserializationContext ctxt) throws IOException, com.fasterxml.jackson.core.JsonProcessingException { return null; }
        };

        setField(realBean, "_valueInstantiator", instantiator);
        setField(realBean, "_delegateDeserializer", delegateDeserializer);
        setField(realBean, "_injectables", mock(com.fasterxml.jackson.databind.InjectableValues.class));

        when(instantiator.canCreateFromBoolean()).thenReturn(false);
        when(delegateDeserializer.deserialize(p, ctxt)).thenReturn(delegateResult);
        when(instantiator.createUsingDelegate(ctxt, delegateResult)).thenReturn(finalBean);

        Object result = realBean.deserializeFromBoolean(p, ctxt);

        assertEquals(finalBean, result);
        verify(instantiator).createUsingDelegate(ctxt, delegateResult);
    }

    /**
     * Test Path 2: _delegateDeserializer is NOT null AND _valueInstantiator.canCreateFromBoolean() is TRUE
     * This should fall through to the boolean parsing logic.
     */
    @Test
    public void testDeserializeWithDelegateButCanCreateFromBoolean() throws IOException {
        when(instantiator.canCreateFromBoolean()).thenReturn(true);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_TRUE);
        when(instantiator.createFromBoolean(ctxt, true)).thenReturn("true_val");

        Object result = beanDeserializerBase.deserializeFromBoolean(p, ctxt);

        assertEquals("true_val", result);
        verify(instantiator).createFromBoolean(ctxt, true);
    }

    /**
     * Test Path 3: _delegateDeserializer is null
     * This should fall through to the boolean parsing logic.
     */
    @Test
    public void testDeserializeWithNoDelegate() throws IOException {
        setField(beanDeserializerBase, "_delegateDeserializer", null);
        when(instantiator.canCreateFromBoolean()).thenReturn(true); // Should not be called
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_FALSE);
        when(instantiator.createFromBoolean(ctxt, false)).thenReturn("false_val");

        Object result = beanDeserializerBase.deserializeFromBoolean(p, ctxt);

        assertEquals("false_val", result);
        verify(instantiator).createFromBoolean(ctxt, false);
    }

    /**
     * Test Path 4: Fallthrough logic with VALUE_FALSE
     */
    @Test
    public void testDeserializeBooleanFalse() throws IOException {
        setField(beanDeserializerBase, "_delegateDeserializer", null);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_FALSE);
        when(instantiator.createFromBoolean(ctxt, false)).thenReturn(false);

        Object result = beanDeserializerBase.deserializeFromBoolean(p, ctxt);

        assertEquals(false, result);
    }
}
